import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as a}from"./chunks/M-S-HDS-CF6.onaQ35vF.js";import{_ as s,o as n,c as r,a3 as o}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Abonné CareLink","description":"","frontmatter":{"source_hash":"29d4533605","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/install/carelinkfollow.md","filePath":"fr/install/carelinkfollow.md"}'),l={name:"fr/install/carelinkfollow.md"};function p(d,t,c,m,u,v){return n(),r("div",null,[...t[0]||(t[0]=[o('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   CareLink Follower</p></div><br><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Les serveurs CareLink font l&#39;objet de modifications fréquentes qui peuvent casser cette fonction.<br><strong>En cas de problème, utilisez la <a href="./download.html#pre-release">dernière pré-version</a>.</strong><br> Envisagez plutôt d&#39;utiliser <a href="./companion.html">Companion App</a> sur le téléphone principal, et xDrip <a href="./xdripfollower.html">Sync</a> ou Nightscout pour partager les données.<br> L&#39;authentification de l&#39;application CarePartner est valable 1 semaine : même si xDrip ne peut pas se connecter à CareLink pendant quelques jours (par exemple faute de connexion Internet), il pourra renouveler la connexion (actualiser le jeton) automatiquement en arrière-plan dès qu&#39;il pourra de nouveau joindre CareLink, sans que vous ayez à vous reconnecter manuellement dans le navigateur. La restriction sur le compte utilisateur s&#39;applique aussi à ce processus d&#39;authentification :<br><strong>xDrip doit utiliser un compte abonné dédié, vous ne pouvez pas utiliser le même abonné pour d&#39;autres applications ou d&#39;autres téléphones.</strong></p></div><br><p>Cela fonctionne aussi pour un CGM Simplera autonome (utilisé sans pompe associée) qui envoie ses données vers CareLink.</p><p>Sélectionnez le pays dans lequel vous avez enregistré votre utilisateur CareLink.</p><div class="admonition xdripitem"><p class="admonition-title">Pays CareLink</p><p> Sélectionner votre pays CareLink.</p></div><p>Indiquez le nom d&#39;utilisateur du patient si vous utilisez un compte de care partner avec plusieurs patients.</p><div class="admonition xdripitem"><p class="admonition-title">Nom d&#39;utilisateur du patient CareLink</p><p> Nom d&#39;utilisateur du patient CareLink (facultatif)</p></div><p>xDrip ouvre le site d&#39;authentification CareLink : saisissez vos identifiants pour vous connecter.</p><div class="admonition xdripitem"><p class="admonition-title">Connexion</p><p> Se connecter avec le navigateur</p></div><p>Le délai de grâce est un temps d&#39;attente supplémentaire après la réception de la dernière valeur + 5 minutes.<br> Il sert à éviter un blocage par le serveur si xDrip envoie des requêtes trop fréquentes.</p><div class="admonition xdripitem"><p class="admonition-title">Délai de grâce</p><p> Délai de grâce pour la demande de données en secondes</p></div><p>L&#39;intervalle de collecte des données manquées est un temps d&#39;attente supplémentaire après la réception de la dernière valeur + 5 minutes + délai de grâce.<br> Il sert à éviter un blocage par le serveur si xDrip envoie des requêtes trop fréquentes.</p><div class="admonition xdripitem"><p class="admonition-title">Intervalle de collecte de données manquées</p><p> Intervalle de collecte après les données manquées en minutes</p></div><br><h4 id="treatments" tabindex="-1">Traitements <a class="header-anchor" href="#treatments" aria-label="Permalink to &quot;Traitements {#treatments}&quot;">​</a></h4><p>Vous pouvez télécharger les traitements et recevoir les notifications.</p><div class="admonition xdripitem"><p class="admonition-title">Glycémies capillaires <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Télécharger les glycémies capillaires depuis CareLink</p></div><div class="admonition xdripitem"><p class="admonition-title">Bolus <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Télécharger les bolus depuis CareLink</p></div><div class="admonition xdripitem"><p class="admonition-title">Repas <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Télécharger les repas depuis CareLink</p></div><div class="admonition xdripitem"><p class="admonition-title">Notifications <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Télécharger les notifications de CareLink</p></div><br><h4 id="status-line" tabindex="-1">Ligne d&#39;état <a class="header-anchor" href="#status-line" aria-label="Permalink to &quot;Ligne d&#39;état {#status-line}&quot;">​</a></h4><p>L&#39;état du capteur et l&#39;état de la pompe peuvent être activés dans l&#39;option <a href="./../use/lesscommon.html#extra-status-line">Ligne d&#39;état supplémentaire</a>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Paramètres<br>   Paramètres moins courants<br>   Ligne d&#39;état supplémentaire</p></div><div class="admonition xdripitem"><p class="admonition-title">Statut externe <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> État de l&#39;affichage d&#39;autres applications comme AndroidAPS</p></div><div class="admonition xdripitem"><p class="admonition-title">État de la pompe <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher les informations d’état de pompe si disponible</p></div><p>Les informations de la pompe (état, basal) sont <u>uniquement visibles</u> dans la ligne d&#39;état et <strong>ne peuvent pas être envoyées vers Nightscout/Tidepool</strong>.</p><img src="'+a+'" style="zoom:75%;"><br><p>Si aucune donnée n&#39;apparaît et qu&#39;aucun message d&#39;erreur ne s&#39;affiche, vous devrez peut-être <a href="./../use/startsensor.html#followers-and-companion-apps">Démarrer le capteur</a>.</p><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',33)])])}const x=s(l,[["render",p]]);export{_ as __pageData,x as default};
